<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/auth.php';require_once __DIR__.'/../config/helpers.php';requireRole('dosen');$base='..';$assetBase='../assets';$pageTitle='Dashboard Dosen';require __DIR__.'/../partials/head.php'; ?><div class="dashboard-layout"><?php require __DIR__.'/../partials/sidebar.php'; ?><main class="main"><div class="mobile-head"><b>Sistem Absensi QR</b><button class="menu-toggle">☰</button></div><header class="topbar"><div><h1>Dashboard Dosen</h1><p>Kelola sesi, QR perkuliahan, dan presensi kelas.</p></div><div class="top-actions"><a class="btn btn-ghost" href="../index.php">↗ Beranda</a></div></header>
<?php $did=(int)($pdo->query("SELECT d.id FROM dosen d JOIN users u ON u.username=d.nidn WHERE u.id=".userId())->fetchColumn()?:0);$st=$pdo->prepare('SELECT COUNT(*) FROM sesi_absensi s JOIN jadwal j ON j.id=s.jadwal_id WHERE j.dosen_id=? AND s.tanggal=CURDATE()');$st->execute([$did]);$today=(int)$st->fetchColumn();$st=$pdo->prepare('SELECT COUNT(*) FROM jadwal WHERE dosen_id=?');$st->execute([$did]);$jad=(int)$st->fetchColumn();$st=$pdo->prepare('SELECT s.*,mk.nama_mk,k.nama_kelas FROM sesi_absensi s JOIN jadwal j ON j.id=s.jadwal_id JOIN mata_kuliah mk ON mk.id=j.mata_kuliah_id JOIN kelas k ON k.id=j.kelas_id WHERE j.dosen_id=? ORDER BY s.tanggal DESC,s.id DESC LIMIT 6');$st->execute([$did]);$rows=$st->fetchAll(); ?><div class="stats"><div class="stat"><small>Sesi hari ini</small><strong><?=$today?></strong><span>dibuat hari ini</span></div><div class="stat"><small>Jadwal mengajar</small><strong><?=$jad?></strong><span>terdaftar</span></div><div class="stat"><small>QR sesi</small><strong>LIVE</strong><span>siap dibagikan</span></div><div class="stat"><small>Validasi</small><strong>GPS</strong><span>radius lokasi</span></div></div><div class="content-grid"><section class="section"><div class="section-head"><h2>Sesi terbaru</h2><a class="btn btn-primary" href="sesi.php">+ Buat sesi</a></div><div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Mata Kuliah</th><th>Kelas</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['tanggal'])?></td><td><?=e($r['nama_mk'])?></td><td><?=e($r['nama_kelas'])?></td><td><span class="badge green"><?=e($r['status'])?></span></td><td><a class="btn btn-ghost" href="absensi.php?sesi=<?=$r['id']?>">Lihat</a></td></tr><?php endforeach;?></tbody></table></div></section><section class="section"><h2 style="font-size:15px">Alur mengajar</h2><div class="notice" style="margin-top:15px">Buat sesi → tampilkan QR → kirim ke grup kelas → mahasiswa scan → server validasi lokasi & waktu → daftar hadir terisi otomatis.</div></section></div>
